/**
 * Advisory-only translation for hybrid connectivity resources:
 * - aws_vpn_connection / aws_vpn_gateway -> TGW_HYBRID_CONNECTIVITY
 * - aws_dx_connection / aws_dx_gateway -> TGW_HYBRID_CONNECTIVITY
 * - aws_ec2_transit_gateway_peering_attachment -> TGW_PEERING_ADVISORY
 *
 * These resources have no automated mapping; they emit warning findings
 * with structured migration guidance.
 *
 * @module structural/hybrid-connectivity-mapping
 * @generated by code-generator (TASK-NET-006)
 */

import type { TranslationContext, EngineResult } from '../mapping-engine.js';
import { createFinding } from '../direct/attribute-transformer.js';

// ---------------------------------------------------------------------------
// Migration guidance per provider
// ---------------------------------------------------------------------------

const AZURE_VPN_STEPS: readonly string[] = [
  'Create Azure VPN Gateway in the Virtual Hub',
  'Configure site-to-site VPN connection with matching PSK and IKE settings',
  'Set up BGP peering if the source used dynamic routing',
  'Verify IPsec/IKE policy alignment (encryption, integrity, DH group)',
];

const GCP_VPN_STEPS: readonly string[] = [
  'Create Cloud VPN Gateway (HA VPN recommended)',
  'Configure VPN tunnels with matching PSK and IKE settings',
  'Set up Cloud Router with BGP sessions for dynamic routing',
  'Verify IPsec/IKE policy alignment (encryption, integrity, DH group)',
];

const AZURE_DX_STEPS: readonly string[] = [
  'Provision Azure ExpressRoute circuit with matching bandwidth',
  'Configure ExpressRoute Gateway in the Virtual Hub',
  'Set up private peering with matching VLAN and BGP ASN',
  'Coordinate with connectivity provider for cross-connect',
];

const GCP_DX_STEPS: readonly string[] = [
  'Provision Cloud Interconnect (Dedicated or Partner)',
  'Create VLAN attachment on Cloud Router',
  'Configure BGP sessions with matching ASN',
  'Coordinate with connectivity provider for cross-connect',
];

// ---------------------------------------------------------------------------
// Public entry point
// ---------------------------------------------------------------------------

/**
 * Advisory-only translation for hybrid connectivity resources (VPN, Direct
 * Connect, and TGW peering). Emits zero translated resources and structured
 * migration findings.
 */
export function translateHybridConnectivity(
  ctx: TranslationContext,
): EngineResult {
  const { resource } = ctx;
  const sourceType = resource.sourceType;
  const provider = ctx.targetProvider === 'azure' ? 'Azure' : 'GCP';

  // TGW peering attachment
  if (sourceType === 'aws_ec2_transit_gateway_peering_attachment') {
    const peeringSteps = ctx.targetProvider === 'azure'
      ? [
          'Azure Virtual WAN does not support cross-region hub peering natively in all SKUs',
          'Consider Azure Global VNet Peering or Virtual WAN hub-to-hub routing',
          'Manually configure routing between hubs if multi-region topology is required',
        ]
      : [
          'GCP Network Connectivity Center supports multi-region hub natively',
          'Create spokes in each region and attach to the same hub',
          'Configure Cloud Router for cross-region dynamic routing',
        ];

    return {
      translated: [],
      findings: [
        createFinding(
          resource.id,
          'warning',
          'TGW_PEERING_ADVISORY',
          `aws_ec2_transit_gateway_peering_attachment has no direct ${provider} equivalent; ` +
            'inter-region connectivity must be configured manually',
          JSON.stringify({ migrationSteps: peeringSteps }),
        ),
      ],
    };
  }

  // VPN resources
  const isVpn =
    sourceType === 'aws_vpn_connection' || sourceType === 'aws_vpn_gateway';
  if (isVpn) {
    const steps = ctx.targetProvider === 'azure' ? AZURE_VPN_STEPS : GCP_VPN_STEPS;
    const target = ctx.targetProvider === 'azure'
      ? 'Azure VPN Gateway'
      : 'Cloud VPN Gateway (HA VPN)';

    return {
      translated: [],
      findings: [
        createFinding(
          resource.id,
          'warning',
          'TGW_HYBRID_CONNECTIVITY',
          `${sourceType} requires manual migration to ${target}; ` +
            'automated translation not supported',
          JSON.stringify({
            migrationSteps: steps,
            alternatives: [target],
          }),
        ),
      ],
    };
  }

  // Direct Connect / DX resources
  const isDx =
    sourceType === 'aws_dx_connection' || sourceType === 'aws_dx_gateway';
  if (isDx) {
    const steps = ctx.targetProvider === 'azure' ? AZURE_DX_STEPS : GCP_DX_STEPS;
    const target = ctx.targetProvider === 'azure'
      ? 'Azure ExpressRoute'
      : 'Cloud Interconnect';

    return {
      translated: [],
      findings: [
        createFinding(
          resource.id,
          'warning',
          'TGW_HYBRID_CONNECTIVITY',
          `${sourceType} requires manual migration to ${target}; ` +
            'automated translation not supported',
          JSON.stringify({
            migrationSteps: steps,
            alternatives: [target],
          }),
        ),
      ],
    };
  }

  // Generic fallback for any other hybrid type
  return {
    translated: [],
    findings: [
      createFinding(
        resource.id,
        'warning',
        'TGW_HYBRID_CONNECTIVITY',
        `${sourceType} requires manual migration to ${provider} equivalent; ` +
          'no automated translation available',
      ),
    ],
  };
}
